from taf.gnb.oam.coam.cu.schemas.base import SchemaField
from taf.gnb.oam.coam.cu.schemas.internal.trs.certificate_information_v1 import CertificateDetails, CertificateInfoTRSV1


class DetailsTRSV2(CertificateDetails):
    key_pool_type = SchemaField(name='keyPoolType', optional=True)

    def __init__(self, authority_key_identifier, ca_type, config_dn, crl_dp_uri, extended_key_usage, fingerprint,
                 issued_by, issued_to, key_id_criticality, key_usage, serial_number, signature_algorithm,
                 subject_alternate_name, subject_public_key_algorithm, trust_chain, valid_from, valid_to, version,
                 key_pool_type):
        self.key_pool_type = key_pool_type
        super(DetailsTRSV2, self).__init__(authority_key_identifier, ca_type, config_dn, crl_dp_uri, extended_key_usage,
                                           fingerprint, issued_by, issued_to, key_id_criticality, key_usage,
                                           serial_number, signature_algorithm, subject_alternate_name,
                                           subject_public_key_algorithm, trust_chain, valid_from, valid_to, version)


class CertificatesInfoTRSV2(CertificateInfoTRSV1):
    details = SchemaField(name='details', klass=DetailsTRSV2, not_null=True)

    def __init__(self, id, type, details):
        self.details = details
        super(CertificatesInfoTRSV2, self).__init__(id, type, details)
